/** `body` is a variant: exactly one of `notes`, `note_row`, `stamp`, `stamp_row` is
 * present, and which one is in the discriminant. The variant has no
 * accessor of its own -- there is no one thing to hand back -- and
 * each arm's members are below, guarded.
 *
 * message.body.notes, present when the discriminant selects `op.notes`.
 *
 * Reading another arm's bytes as this one's stays inside the view
 * and means nothing, so the accessor asks first and refuses. The
 * code is `default: error`'s, being the same mistake from the
 * other end.
 */
static inline situ_err_t fzn_notes_local_message_body_notes_view(situ_view_t view, situ_view_t *out)
{
	if (fzn_notes_local_message_op_get(view) != 128u) {
		return SITU_ERR_VERSION;
	}
	return situ_view_sub(view, 2u, FZN_NOTES_LOCAL_NOTES_SIZE_FIXED, out);
}

/* message.body.note_row, present when the discriminant selects `op.note_row`.
 *
 * Reading another arm's bytes as this one's stays inside the view
 * and means nothing, so the accessor asks first and refuses. The
 * code is `default: error`'s, being the same mistake from the
 * other end. */
/** How many bytes `note_row` occupies, for the switch
 * that places whatever follows the variant.
 */
static inline uint32_t fzn_notes_local_message_body_note_row_extent(situ_view_t view)
{
	situ_view_t whole;

	if (situ_view_sub(view, 2u, situ_remaining_u32(view.limit, 2u), &whole) != SITU_OK) {
		return 0u;
	}
	return fzn_notes_local_note_row_extent(whole);
}
static inline situ_err_t fzn_notes_local_message_body_note_row_view(situ_view_t view, situ_view_t *out)
{
	if (fzn_notes_local_message_op_get(view) != 129u) {
		return SITU_ERR_VERSION;
	}
	situ_view_t whole;

	if (situ_view_sub(view, 2u, situ_remaining_u32(view.limit, 2u), &whole) != SITU_OK) {
		return SITU_ERR_BOUNDS;
	}
	const uint32_t size = fzn_notes_local_note_row_extent(whole);
	return situ_view_sub(view, 2u, size, out);
}

